import csv
import io


def parse_csv(raw_csv: str):
    width = 7
    schema = (
        "uniq-name", "value", "type", "confidence",
        "severity", "product", "comment",
    )

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )

    pending = []
    columns = None
    for record in records:
        if len(record) == width:
            names = [field.strip().casefold() for field in record]
            names[0] = names[0].lstrip("#").strip()
            if tuple(names) == schema:
                columns = record
                break
        pending.append(record)

    if columns is None:
        for index, record in enumerate(pending):
            if not record or (len(record) == 1 and not record[0].strip()):
                continue
            if record[0].strip().casefold() == "sep=" and record[1:] == [""]:
                continue
            if len(record) == 1 and record[0].lstrip().startswith("#"):
                continue
            columns = record
            records = iter(pending[index + 1:])
            break
        else:
            return {"columns": [], "rows": []}

    def fit(record):
        if len(record) > width:
            return record[:width - 1] + [",".join(record[width - 1:])]
        return record + [""] * (width - len(record))

    return {"columns": fit(columns), "rows": [fit(record) for record in records]}
